  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const text = renderInvoiceText(issued);
  assert(!text.includes('Paid:'));
});

test('renderInvoiceText complete invoice with all features', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
    terms: 'NET14',
  }).value;
  const withVoucher = applyVoucher(invoice, { code: 'SAVE', amount: 500 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: Math.floor(totals.total / 2), date: '2026-10-10' }).value;

  const text = renderInvoiceText(paid);
  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(text.includes('Kite & Co'));
  assert.ok(text.includes('10 x Design work'));
  assert.ok(text.includes('Discount: €'));
  assert.ok(text.includes('VAT: €'));
  assert.ok(text.includes('Voucher: €5.00'));
  assert.ok(text.includes('Total: €'));
  assert.ok(text.includes('Due: 2026-10-21'));
  assert.ok(text.includes('Paid: €'));
});

