import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText renders a draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Kite & Co');
  assert.equal(lines[2], '2 x Design work (hour) @ €85.00 = €170.00');
  assert.ok(lines[3].includes('Discount: €'));
  assert.ok(lines[4].startsWith('VAT: €'));
  assert.ok(lines[5].startsWith('Total: €'));
  assert.ok(lines[5].includes('200'));
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2026-0001');
  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText renders multiple invoice lines', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 5 },
      { sku: 'SUPPORT-HOUR', qty: 3 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('DRAFT'));
  assert.ok(text.includes('Kite & Co'));
  assert.ok(text.includes('2 x Design work (hour) @ €85.00 = €170.00'));
  assert.ok(text.includes('5 x Icon set (24 icons) @ €9.80 = €49.00'));
  assert.ok(text.includes('3 x Support (hour) @ €72.50 = €217.50'));
  assert.ok(text.includes('Discount: €'));
  assert.ok(text.includes('VAT: €'));
  assert.ok(text.includes('Total: €'));
});

test('renderInvoiceText formats amounts correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('1 x Logo package @ €1,200.00 = €1,200.00'));
  assert.ok(text.includes('100 x Sticker sheet @ €0.50 = €50.00'));
  assert.ok(text.includes('Discount: €'));
  assert.ok(text.includes('VAT: €'));
  assert.ok(text.includes('Total: €'));
});

test('renderInvoiceText handles unknown customer', () => {
  const invoice = {
    customerId: 'C-999',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Unknown Customer');
});

test('renderInvoiceText renders invoice with issued number', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const existingNumbers = ['INV-2026-0001', 'INV-2026-0005'];
  const issued = issueInvoice(invoice, existingNumbers).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2026-0006');
});

test('renderInvoiceText handles VAT-exempt items', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('DRAFT'));
  assert.ok(text.includes('Blue Fern Bakery'));
  assert.ok(text.includes('Brand workshop'));
  assert.ok(text.includes('Total: €600.00'));
});

test('renderInvoiceText shows line discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Discount: €'));
});

test('renderInvoiceText includes bulk discount in line', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Discount: €'));
});

test('renderInvoiceText shows voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE10', amount: 1000 }).value;
  const text = renderInvoiceText(withVoucher);
  assert.ok(text.includes('Voucher: €10.00'));
});

test('renderInvoiceText does not show voucher when zero', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert(!text.includes('Voucher:'));
});

test('renderInvoiceText shows due date', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const text = renderInvoiceText(issued);
  assert.ok(text.includes('Due: 2026-10-21'));
});

test('renderInvoiceText does not show due date when none', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const partial = recordPayment(issued, { amount: Math.floor(totals.total / 2), date: '2026-10-10' }).value;

  const text = renderInvoiceText(partial);
  assert.ok(text.includes('Paid: €'));
});

test('renderInvoiceText does not show paid when no payments', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const text = renderInvoiceText(issued);
  assert(!text.includes('Paid:'));
});

test('renderInvoiceText complete invoice with all features', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
    terms: 'NET14',
  }).value;
  const withVoucher = applyVoucher(invoice, { code: 'SAVE', amount: 500 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: Math.floor(totals.total / 2), date: '2026-10-10' }).value;

  const text = renderInvoiceText(paid);
  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(text.includes('Kite & Co'));
  assert.ok(text.includes('10 x Design work'));
  assert.ok(text.includes('Discount: €'));
  assert.ok(text.includes('VAT: €'));
  assert.ok(text.includes('Voucher: €5.00'));
  assert.ok(text.includes('Total: €'));
  assert.ok(text.includes('Due: 2026-10-21'));
  assert.ok(text.includes('Paid: €'));
});
